//! Pure UX rule kernels proven by the Lean 4 suite in `apps/nano/lean-proofs/Nano/`.
//! Verified against `ux_proof_vectors.csv` generated by `UxVectors.lean`.
const std = @import("std");

pub const SessionFooterLayout = struct {
    pad: u32,
    show_checkout: bool,
    checkout_text_max: u32,
    show_branch: bool,
    branch_text_max: u32,
    show_actions: bool,
};

/// `Nano.FrameSchedule.sessionFooterLayout`
pub fn sessionFooterLayout(slot_w: u32) SessionFooterLayout {
    if (slot_w >= 260) {
        const text_max = @min(@as(u32, 126), (slot_w - 92) / 2);
        return .{
            .pad = 10,
            .show_checkout = true,
            .checkout_text_max = text_max,
            .show_branch = true,
            .branch_text_max = text_max,
            .show_actions = slot_w >= 380,
        };
    }
    if (slot_w >= 156) {
        return .{
            .pad = 10,
            .show_checkout = true,
            .checkout_text_max = 0,
            .show_branch = true,
            .branch_text_max = @min(@as(u32, 126), slot_w - 86),
            .show_actions = false,
        };
    }
    if (slot_w >= 80) {
        return .{
            .pad = 10,
            .show_checkout = true,
            .checkout_text_max = 0,
            .show_branch = true,
            .branch_text_max = 0,
            .show_actions = false,
        };
    }
    if (slot_w >= 48) {
        return .{
            .pad = 10,
            .show_checkout = false,
            .checkout_text_max = 0,
            .show_branch = true,
            .branch_text_max = 0,
            .show_actions = false,
        };
    }
    return .{
        .pad = 0,
        .show_checkout = false,
        .checkout_text_max = 0,
        .show_branch = false,
        .branch_text_max = 0,
        .show_actions = false,
    };
}

/// `Nano.OverlayMutex`
pub const OverlayMutex = struct {
    pub const OverlayKind = enum(u8) {
        none = 0,
        session_search = 1,
        context_pinned = 2,
        agent_work_pinned = 3,
        account_usage_open = 4,
        star_menu = 5,
        updates_popover = 6,
        action_menu = 7,
        filter_menu = 8,
        more_menu = 9,
        space_menu = 10,
        checkout_menu = 11,
        ref_menu = 12,
        chat_menu = 13,
        link_menu = 14,
        strip_menu = 15,
        account_menu = 16,
        model_picker = 17,
        custom_theme = 18,
        theme_import = 19,
        close_choice = 20,
        settings_recording = 21,
        action_command_review = 22,
        command_palette = 23,
        open_chooser = 24,
        project_setup = 25,
        setup = 26,
    };

    pub fn tier(k: OverlayKind) u8 {
        return switch (k) {
            .none => 0,
            .session_search,
            .context_pinned,
            .agent_work_pinned,
            .account_usage_open,
            .star_menu,
            .updates_popover,
            .action_menu,
            .filter_menu,
            .more_menu,
            .space_menu,
            .checkout_menu,
            .ref_menu,
            .chat_menu,
            .link_menu,
            .strip_menu,
            .account_menu,
            .model_picker,
            => 1,
            .custom_theme,
            .theme_import,
            .close_choice,
            .settings_recording,
            .action_command_review,
            => 2,
            .command_palette => 3,
            .open_chooser, .project_setup, .setup => 4,
        };
    }

    pub fn activeLayer(k: OverlayKind) u8 {
        return switch (tier(k)) {
            0 => 0,
            1 => 4,
            2 => 6,
            3 => 7,
            else => 8,
        };
    }

    pub fn blocksBackgroundInput(k: OverlayKind) bool {
        return k != .none;
    }

    pub fn keepsKeyboard(k: OverlayKind) bool {
        return k != .none;
    }

    pub fn scrimActive(k: OverlayKind) bool {
        return tier(k) >= 2;
    }

    pub fn allowsCanvasClick(k: OverlayKind) bool {
        return k == .none;
    }

    pub fn openOverlay(cur: OverlayKind, next: OverlayKind) OverlayKind {
        if (next == .none) return .none;
        if (tier(cur) <= 1 or tier(next) >= tier(cur)) return next;
        return cur;
    }

    pub fn toggleOverlay(cur: OverlayKind, target: OverlayKind) OverlayKind {
        if (cur == target) return .none;
        return openOverlay(cur, target);
    }
};

/// `Nano.EscapeTermination`
pub const EscapeTermination = struct {
    pub const EscAction = enum(u8) {
        noop = 0,
        dismiss_setup = 1,
        dismiss_project_setup = 2,
        dismiss_open_chooser = 3,
        dismiss_palette = 4,
        dismiss_picker = 5,
        cancel_recording = 6,
        dismiss_close_choice = 7,
        dismiss_dialog = 8,
        dismiss_popup_menu = 9,
        dismiss_image_preview = 10,
        close_write = 11,
        cancel_queue_edit = 12,
        wizard_step_back = 13,
        close_completion = 14,
        close_settings = 15,
        interrupt_agent = 16,
    };

    pub const EscState = struct {
        setup_open: bool = false,
        project_setup_open: bool = false,
        open_chooser_open: bool = false,
        palette_open: bool = false,
        picker_open: bool = false,
        settings_recording: bool = false,
        close_choice_open: bool = false,
        dialog_open: bool = false,
        popup_menu_open: bool = false,
        image_preview_open: bool = false,
        write_open: bool = false,
        queue_edit_open: bool = false,
        wizard_can_back: bool = false,
        composer_completion_open: bool = false,
        settings_open: bool = false,
        agent_busy: bool = false,
    };

    pub fn escWeight(s: EscState) u32 {
        return @as(u32, @intFromBool(s.setup_open)) +
            @intFromBool(s.project_setup_open) +
            @intFromBool(s.open_chooser_open) +
            @intFromBool(s.palette_open) +
            @intFromBool(s.picker_open) +
            @intFromBool(s.settings_recording) +
            @intFromBool(s.close_choice_open) +
            @intFromBool(s.dialog_open) +
            @intFromBool(s.popup_menu_open) +
            @intFromBool(s.image_preview_open) +
            @intFromBool(s.write_open) +
            @intFromBool(s.queue_edit_open) +
            @intFromBool(s.wizard_can_back) +
            @intFromBool(s.composer_completion_open) +
            @intFromBool(s.settings_open) +
            @intFromBool(s.agent_busy);
    }

    pub fn escAction(s: EscState) EscAction {
        if (s.setup_open) return .dismiss_setup;
        if (s.project_setup_open) return .dismiss_project_setup;
        if (s.open_chooser_open) return .dismiss_open_chooser;
        if (s.palette_open) return .dismiss_palette;
        if (s.picker_open) return .dismiss_picker;
        if (s.settings_recording) return .cancel_recording;
        if (s.close_choice_open) return .dismiss_close_choice;
        if (s.dialog_open) return .dismiss_dialog;
        if (s.popup_menu_open) return .dismiss_popup_menu;
        if (s.image_preview_open) return .dismiss_image_preview;
        if (s.write_open) return .close_write;
        if (s.queue_edit_open) return .cancel_queue_edit;
        if (s.wizard_can_back) return .wizard_step_back;
        if (s.composer_completion_open) return .close_completion;
        if (s.settings_open) return .close_settings;
        if (s.agent_busy) return .interrupt_agent;
        return .noop;
    }

    pub fn stepEsc(s: EscState) EscState {
        var out = s;
        switch (escAction(s)) {
            .dismiss_setup => out.setup_open = false,
            .dismiss_project_setup => out.project_setup_open = false,
            .dismiss_open_chooser => out.open_chooser_open = false,
            .dismiss_palette => out.palette_open = false,
            .dismiss_picker => out.picker_open = false,
            .cancel_recording => out.settings_recording = false,
            .dismiss_close_choice => out.close_choice_open = false,
            .dismiss_dialog => out.dialog_open = false,
            .dismiss_popup_menu => out.popup_menu_open = false,
            .dismiss_image_preview => out.image_preview_open = false,
            .close_write => out.write_open = false,
            .cancel_queue_edit => out.queue_edit_open = false,
            .wizard_step_back => out.wizard_can_back = false,
            .close_completion => out.composer_completion_open = false,
            .close_settings => out.settings_open = false,
            .interrupt_agent => out.agent_busy = false,
            .noop => {},
        }
        return out;
    }

    pub fn restoresComposer(a: EscAction) bool {
        return switch (a) {
            .dismiss_project_setup,
            .dismiss_open_chooser,
            .dismiss_palette,
            .dismiss_picker,
            .dismiss_close_choice,
            .dismiss_dialog,
            .dismiss_popup_menu,
            .close_write,
            .cancel_queue_edit,
            .close_completion,
            .close_settings,
            => true,
            else => false,
        };
    }
};

/// `Nano.HoverStability`
pub const HoverStability = struct {
    pub const tab_pad_total: u32 = 16;

    pub fn tabControlsReserve(cell_w: u32, is_active: bool, can_close: bool) u32 {
        return if (can_close and (is_active or cell_w >= 72) and cell_w >= 40) 16 else 0;
    }

    pub fn tabLabelWidth(cell_w: u32, is_active: bool, is_hovered: bool, can_close: bool) u32 {
        _ = is_hovered;
        const res = tabControlsReserve(cell_w, is_active, can_close);
        if (cell_w <= tab_pad_total + res) return 0;
        return cell_w - tab_pad_total - res;
    }

    pub fn tabCloseGlyphOpacityPct(is_active: bool, is_hovered: bool, can_close: bool) u32 {
        if (!can_close) return 0;
        if (is_hovered) return 100;
        if (is_active) return 80;
        return 0;
    }

    pub fn sidebarTitleMaxW(row_w: u32, pad_l: u32, pad_r: u32, time_reserve: u32, is_hovered: bool) u32 {
        _ = is_hovered;
        return row_w -| (pad_l + pad_r + time_reserve);
    }

    pub fn hitTargetSize(w: u32, h: u32) struct { w: u32, h: u32 } {
        return .{ .w = @max(w, 32), .h = @max(h, 32) };
    }
};

/// `Nano.FocusAndClose`
pub const FocusAndClose = struct {
    pub const TextFocusOwner = enum(u8) {
        none = 0,
        modal_field = 1,
        palette_input = 2,
        sidebar_search = 3,
        write_editor = 4,
        design_note = 5,
        browse_url = 6,
        composer = 7,
    };

    pub fn activeTextOwner(
        has_modal: bool,
        palette_open: bool,
        sidebar_search_focus: bool,
        write_open: bool,
        design_note_focused: bool,
        browse_url_focused: bool,
        has_chat_area: bool,
    ) TextFocusOwner {
        if (has_modal) return .modal_field;
        if (palette_open) return .palette_input;
        if (sidebar_search_focus) return .sidebar_search;
        if (write_open) return .write_editor;
        if (design_note_focused) return .design_note;
        if (browse_url_focused) return .browse_url;
        if (has_chat_area) return .composer;
        return .none;
    }

    pub const SurfaceFocus = enum(u8) {
        chat = 0,
        host = 1,
        design_canvas = 2,
        files = 3,
    };

    pub const CloseDecision = enum(u8) {
        noop = 0,
        ask_archive_choice = 1,
        confirm_archive_choice = 2,
        close_host_tab = 3,
        close_design_canvas = 4,
        close_files = 5,
        close_pane_tab = 6,
        close_split_pane = 7,
        close_workspace_tab = 8,
    };

    pub fn decideClose(
        surface: SurfaceFocus,
        close_choice_open: bool,
        group_tabs: u32,
        split_panes: u32,
        host_bg_open: bool,
        expanded: bool,
        is_only_new_chat: bool,
        needs_ask: bool,
    ) CloseDecision {
        if (close_choice_open) return .confirm_archive_choice;
        return switch (surface) {
            .host => .close_host_tab,
            .design_canvas => .close_design_canvas,
            .files => .close_files,
            .chat => blk: {
                if (group_tabs > 1) break :blk .close_pane_tab;
                if (split_panes > 1) break :blk .close_split_pane;
                if (!expanded and host_bg_open) break :blk .close_host_tab;
                if (is_only_new_chat) break :blk .noop;
                if (needs_ask) break :blk .ask_archive_choice;
                break :blk .close_workspace_tab;
            },
        };
    }

    pub fn splitPaneBorderPct(split_count: u32, is_focused: bool) u32 {
        if (split_count <= 1) return 0;
        return if (is_focused) 100 else 28;
    }
};

/// `Nano.TabNavModel`
pub const TabNavModel = struct {
    pub fn stepFlatTab(total: u32, cur: u32, forward: bool) u32 {
        if (total <= 1) return if (total == 0) 0 else @min(cur, total - 1);
        const c = @min(cur, total - 1);
        return if (forward) (c + 1) % total else (c + total - 1) % total;
    }
};

/// `Nano.KeymapPartition`
pub const KeymapPartition = struct {
    pub const Chord = struct {
        code: u21,
        cmd: bool = false,
        ctrl: bool = false,
        alt: bool = false,
        shift: bool = false,

        pub fn eql(a: Chord, b: Chord) bool {
            return a.code == b.code and a.cmd == b.cmd and a.ctrl == b.ctrl and a.alt == b.alt and a.shift == b.shift;
        }
    };

    pub const key_esc: u21 = 256;
    pub const key_enter: u21 = 257;
    pub const key_left: u21 = 258;
    pub const key_right: u21 = 259;
    pub const key_up: u21 = 260;
    pub const key_down: u21 = 261;

    pub const cycle_ui_mode: Chord = .{ .code = 'm', .cmd = true, .shift = true };
    pub const toggle_design_canvas: Chord = .{ .code = 'd', .cmd = true, .alt = true };

    pub const fixed_window_chords = [_]Chord{
        cycle_ui_mode,
        toggle_design_canvas,
        .{ .code = 'w', .cmd = true },
        .{ .code = 'k', .cmd = true },
        .{ .code = 'l', .cmd = true },
        .{ .code = 'q', .cmd = true },
        .{ .code = 'h', .cmd = true },
        .{ .code = 'm', .cmd = true },
        .{ .code = '=', .cmd = true },
        .{ .code = '-', .cmd = true },
        .{ .code = '0', .cmd = true },
        .{ .code = '[', .cmd = true },
        .{ .code = ']', .cmd = true },
        .{ .code = '[', .cmd = true, .shift = true },
        .{ .code = ']', .cmd = true, .shift = true },
        .{ .code = '1', .ctrl = true },
        .{ .code = '2', .ctrl = true },
        .{ .code = '3', .ctrl = true },
        .{ .code = '4', .ctrl = true },
        .{ .code = '5', .ctrl = true },
        .{ .code = '6', .ctrl = true },
        .{ .code = '7', .ctrl = true },
        .{ .code = '8', .ctrl = true },
        .{ .code = '9', .ctrl = true },
        .{ .code = key_left, .cmd = true, .alt = true },
        .{ .code = key_right, .cmd = true, .alt = true },
        .{ .code = key_up, .cmd = true, .alt = true },
        .{ .code = key_down, .cmd = true, .alt = true },
    };

    pub const composer_reserved_chords = [_]Chord{
        .{ .code = 'a', .cmd = true },
        .{ .code = 'c', .cmd = true },
        .{ .code = 'v', .cmd = true },
        .{ .code = 'x', .cmd = true },
        .{ .code = 'z', .cmd = true },
        .{ .code = 'z', .cmd = true, .shift = true },
        .{ .code = 'a', .ctrl = true },
        .{ .code = 'e', .ctrl = true },
        .{ .code = 'k', .ctrl = true },
        .{ .code = 'u', .ctrl = true },
        .{ .code = 'w', .ctrl = true },
        .{ .code = key_enter },
        .{ .code = key_enter, .shift = true },
    };

    pub const Binding = struct { action_id: u32, chord: Chord };

    pub const default_rebindable_chords = [_]Binding{
        .{ .action_id = 0, .chord = .{ .code = 'n', .cmd = true } },
        .{ .action_id = 1, .chord = .{ .code = 'o', .cmd = true } },
        .{ .action_id = 2, .chord = .{ .code = 'b', .cmd = true } },
        .{ .action_id = 3, .chord = .{ .code = 'd', .cmd = true } },
        .{ .action_id = 4, .chord = .{ .code = 'd', .cmd = true, .shift = true } },
        .{ .action_id = 5, .chord = .{ .code = 'j', .cmd = true } },
        .{ .action_id = 6, .chord = .{ .code = ',', .cmd = true } },
        .{ .action_id = 7, .chord = .{ .code = 'f', .cmd = true } },
        .{ .action_id = 8, .chord = .{ .code = 's', .cmd = true, .shift = true } },
    };

    pub fn memChord(c: Chord, xs: []const Chord) bool {
        for (xs) |x| if (c.eql(x)) return true;
        return false;
    }

    pub fn canBindShortcut(candidate: Chord, action_id: u32, bindings: []const Binding) bool {
        if (memChord(candidate, &fixed_window_chords)) return false;
        if (memChord(candidate, &composer_reserved_chords)) return false;
        for (bindings) |b| if (b.action_id != action_id and b.chord.eql(candidate)) return false;
        return true;
    }
};

/// `Nano.UiMode3`
pub const UiMode3 = struct {
    pub const UiMode = enum(u8) {
        zen = 0,
        developer = 1,
        design = 2,
    };

    pub const ModePolicy = struct {
        shows_workspace_tree: bool,
        shows_multi_axis_filters: bool,
        shows_row_tech_badges: bool,
        shows_git_checkout_chrome: bool,
        shows_prompt_rail: bool,
        shows_action_toolbar: bool,
        shows_grouped_sections: bool,
        shows_dev_trailing_toggles: bool,
        shows_design_canvas_toggle: bool,
        shows_zen_new_session_box: bool,
        suppresses_promos: bool,
        composer_corner_radius: u32,
        trailing_button_count: u32,
    };

    pub fn profileOf(m: UiMode) ModePolicy {
        return switch (m) {
            .zen => .{
                .shows_workspace_tree = false,
                .shows_multi_axis_filters = false,
                .shows_row_tech_badges = false,
                .shows_git_checkout_chrome = false,
                .shows_prompt_rail = false,
                .shows_action_toolbar = false,
                .shows_grouped_sections = false,
                .shows_dev_trailing_toggles = false,
                .shows_design_canvas_toggle = false,
                .shows_zen_new_session_box = true,
                .suppresses_promos = true,
                .composer_corner_radius = 16,
                .trailing_button_count = 1,
            },
            .developer => .{
                .shows_workspace_tree = true,
                .shows_multi_axis_filters = true,
                .shows_row_tech_badges = true,
                .shows_git_checkout_chrome = true,
                .shows_prompt_rail = true,
                .shows_action_toolbar = true,
                .shows_grouped_sections = true,
                .shows_dev_trailing_toggles = true,
                .shows_design_canvas_toggle = false,
                .shows_zen_new_session_box = false,
                .suppresses_promos = false,
                .composer_corner_radius = 16,
                .trailing_button_count = 3,
            },
            .design => .{
                .shows_workspace_tree = false,
                .shows_multi_axis_filters = false,
                .shows_row_tech_badges = false,
                .shows_git_checkout_chrome = false,
                .shows_prompt_rail = false,
                .shows_action_toolbar = false,
                .shows_grouped_sections = false,
                .shows_dev_trailing_toggles = false,
                .shows_design_canvas_toggle = true,
                .shows_zen_new_session_box = true,
                .suppresses_promos = true,
                .composer_corner_radius = 16,
                .trailing_button_count = 2,
            },
        };
    }

    pub fn nextMode(m: UiMode) UiMode {
        return switch (m) {
            .zen => .developer,
            .developer => .design,
            .design => .zen,
        };
    }

    pub fn trailingReservePx(m: UiMode, settings_open: bool) u32 {
        if (settings_open) return 0;
        const p = profileOf(m);
        return 8 + p.trailing_button_count * 28 + (p.trailing_button_count - 1) * 4;
    }

    pub fn effectiveTrailingCount(m: UiMode, settings_open: bool, avail_px: u32, last_slot_px: u32) u32 {
        if (settings_open) return 0;
        if (m == .zen) return 1;
        if (avail_px >= 420 and last_slot_px >= 240) return profileOf(m).trailing_button_count;
        return 1;
    }

    pub fn effectiveTrailingReservePx(m: UiMode, settings_open: bool, avail_px: u32, last_slot_px: u32) u32 {
        const cnt = effectiveTrailingCount(m, settings_open, avail_px, last_slot_px);
        if (cnt == 0) return 0;
        return 8 + cnt * 28 + (cnt - 1) * 4;
    }
};

/// `Nano.DesignCanvas`
pub const DesignCanvas = struct {
    pub const ArtboardPreset = enum(u8) { mobile = 0, tablet = 1, desktop = 2 };

    pub const zoom_min_pct: u32 = 25;
    pub const zoom_max_pct: u32 = 400;

    pub fn presetSize(p: ArtboardPreset) struct { w: u32, h: u32 } {
        return switch (p) {
            .mobile => .{ .w = 390, .h = 844 },
            .tablet => .{ .w = 768, .h = 1024 },
            .desktop => .{ .w = 1440, .h = 900 },
        };
    }

    pub fn clampZoomPct(z: u32) u32 {
        return @min(zoom_max_pct, @max(zoom_min_pct, z));
    }

    pub fn stepZoomPct(z: u32, zoom_in: bool) u32 {
        const next = if (zoom_in) (z * 5) / 4 else (z * 4) / 5;
        return clampZoomPct(if (zoom_in and next == z) z + 1 else next);
    }

    pub fn concentricInner(outer: u32, border: u32, pad: u32) u32 {
        return outer -| (border + pad);
    }

    pub fn clampPinPermille(px: u32, py: u32) struct { x: u32, y: u32 } {
        return .{ .x = @min(px, 1000), .y = @min(py, 1000) };
    }

    pub fn hitTargetValid(w: u32, h: u32) bool {
        return w >= 32 and h >= 32;
    }

    pub fn allowedTypeSize(px: u32) bool {
        return px == 11 or px == 12 or px == 13 or px == 14 or px == 16;
    }

    pub fn motionValid(is_spinner: bool, is_linear: bool, is_multi_part: bool, duration_ms: u32) bool {
        if (is_linear) return is_spinner;
        if (is_multi_part) return duration_ms > 0 and duration_ms < 800;
        return duration_ms > 0 and duration_ms <= 250;
    }

    pub fn contrastRatioX100(lum_a: u32, lum_b: u32) u32 {
        const l_hi = @max(lum_a, lum_b);
        const l_lo = @min(lum_a, lum_b);
        return ((l_hi + 500) * 100) / (l_lo + 500);
    }

    pub fn meetsWcagAA(lum_a: u32, lum_b: u32, large_text: bool) bool {
        return contrastRatioX100(lum_a, lum_b) >= (if (large_text) @as(u32, 300) else @as(u32, 450));
    }

    pub fn auditScore(hit_ok: bool, type_ok: bool, motion_ok: bool, contrast_ok: bool) u32 {
        return @as(u32, @intFromBool(hit_ok)) +
            @intFromBool(type_ok) +
            @intFromBool(motion_ok) +
            @intFromBool(contrast_ok);
    }
};

/// `Nano.BrowseConnect`
pub const BrowseConnect = struct {
    pub const UrlScheme = enum(u8) {
        graff_view = 0,
        http = 1,
        https = 2,
        other = 3,
    };

    pub const BrowserRoute = enum(u8) {
        local_saved_view = 0,
        external_browse = 1,
    };

    pub fn classifyScheme(url: []const u8) UrlScheme {
        const trimmed = std.mem.trim(u8, url, " \t\r\n");
        if (startsWithIgnoreCase(trimmed, "graff-view://")) return .graff_view;
        if (startsWithIgnoreCase(trimmed, "http://")) return .http;
        if (startsWithIgnoreCase(trimmed, "https://")) return .https;
        return .other;
    }

    pub fn routeScheme(s: UrlScheme) BrowserRoute {
        return switch (s) {
            .graff_view => .local_saved_view,
            .http, .https, .other => .external_browse,
        };
    }

    pub fn routeUrl(url: []const u8) BrowserRoute {
        return routeScheme(classifyScheme(url));
    }

    pub const HostKind = enum(u8) { loopback_port = 0, other_host = 1 };

    pub fn loopbackRequestAllowed(host: HostKind, has_origin_header: bool) bool {
        return host == .loopback_port and !has_origin_header;
    }

    pub fn nonceAccepted(seen_before: bool, skew_sec: u32) bool {
        return !seen_before and skew_sec <= 120;
    }

    pub fn pairingCode(be32: u32) u32 {
        return be32 % 1_000_000;
    }

    pub const ConnState = enum(u8) {
        needs_browse_install = 0,
        waiting_browse_launch = 1,
        discovered = 2,
        pairing_pending = 3,
        connected = 4,
        pair_denied = 5,
        token_expired = 6,
    };

    pub const ConnEvent = enum(u8) {
        detected_not_installed = 0,
        binary_found_closed = 1,
        connect_json_read = 2,
        pair_requested = 3,
        user_approved = 4,
        user_denied = 5,
        token_timed_out = 6,
        app_closed = 7,
        revoked = 8,
    };

    pub fn mcpCallsPermitted(s: ConnState) bool {
        return s == .connected;
    }

    pub fn shouldPollFrame(st: ConnState, tab_visible: bool, elapsed_ms: u32, in_flight: bool) bool {
        return st == .connected and tab_visible and !in_flight and elapsed_ms >= 750;
    }

    pub fn nextConnState(cur: ConnState, ev: ConnEvent) ConnState {
        return switch (ev) {
            .detected_not_installed => .needs_browse_install,
            .binary_found_closed => .waiting_browse_launch,
            .connect_json_read => .discovered,
            .pair_requested => if (cur == .discovered) .pairing_pending else cur,
            .user_approved => if (cur == .pairing_pending) .connected else cur,
            .user_denied => .pair_denied,
            .token_timed_out => .token_expired,
            .app_closed => .waiting_browse_launch,
            .revoked => .pair_denied,
        };
    }

    fn startsWithIgnoreCase(hay: []const u8, prefix: []const u8) bool {
        if (hay.len < prefix.len) return false;
        return std.ascii.eqlIgnoreCase(hay[0..prefix.len], prefix);
    }
};

/// `Nano.WindowA11yFocus`
pub const WindowA11yFocus = struct {
    pub const A11yRole = enum(u8) {
        button = 0,
        tab = 1,
        text_field = 2,
        splitter = 3,
        slider = 4,
        checkbox = 5,
        switch_toggle = 6,
        radio_button = 7,
        group = 8,
        static_text = 9,
        list = 10,
        row = 11,
        image = 12,
        menu_button = 13,
        popover = 14,
        link = 15,
    };

    pub fn isInteractiveRole(r: A11yRole) bool {
        return switch (r) {
            .group, .static_text, .list, .image, .popover => false,
            else => true,
        };
    }

    pub fn requiresAccessibleName(r: A11yRole) bool {
        return switch (r) {
            .group, .static_text, .list, .popover => false,
            else => true,
        };
    }

    pub fn allowsFocusRing(r: A11yRole, enabled: bool, keyboard_modality: bool) bool {
        return isInteractiveRole(r) and enabled and keyboard_modality;
    }

    pub fn a11yNodeValid(r: A11yRole, has_label: bool, enabled: bool, focused: bool) bool {
        const name_ok = !requiresAccessibleName(r) or has_label;
        const focus_ok = !focused or (isInteractiveRole(r) and enabled);
        return name_ok and focus_ok;
    }

    pub const WindowFocusState = struct {
        active_win: u32 = 1,
        saved_focus: u32 = 0,
        modal_focus: u32 = 0,
        current_focus: u32 = 0,
        modal_open: bool = false,
        window_focused: bool = true,
    };

    pub fn onWindowBlur(s: WindowFocusState) WindowFocusState {
        var next = s;
        next.window_focused = false;
        next.saved_focus = s.current_focus;
        next.current_focus = 0;
        return next;
    }

    pub fn onWindowFocus(s: WindowFocusState) WindowFocusState {
        var next = s;
        next.window_focused = true;
        next.current_focus = if (s.modal_open) s.modal_focus else s.saved_focus;
        return next;
    }

    pub fn onSwitchWindow(s: WindowFocusState, next_win: u32, next_saved: u32) WindowFocusState {
        if (s.modal_open) return s;
        var next = s;
        next.active_win = next_win;
        next.saved_focus = next_saved;
        next.current_focus = next_saved;
        next.window_focused = true;
        return next;
    }
};
